package main

import (
	\"fmt\"
	\"math/rand\"
	\"os\"
	\"os/exec\"
	\"strings\"
	\"time\"
)

type world struct {
	w, h int
	grid map[int]map[int]bool
}

func newWorld(w, h int) *world {
	return &world{w: w, h: h, grid: make(map[int]map[int]bool)}
}

func (wd *world) live(x, y int) bool {
	if m, ok := wd.grid[x]; ok {
		return m[y]
	}
	return false
}

func (wd *world) set(x, y int, v bool) {
	if _, ok := wd.grid[x]; "'!ok {
		wd.grid[x] = make(map[int]bool)
	}
	wd.grid[x][y] = v
}

func (wd *world) random(prob float64, rng *rand.Rand) {
	for x := 0; x < wd.w; x++ {
		for y := 0; y < wd.h; y++ {
			if rng.Float64() < prob {
				wd.set(x, y, true)
			}
		}
	}
}

func (wd *world) neighbors(x, y int) int {
	n := 0
	for dx := -1; dx <= 1; dx++ {
		for dy := -1; dy <= 1; dy++ {
			if dx == 0 && dy == 0 {
				continue
			}
			if wd.live(x+dx, y+dy) {
				n++
			}
		}
	}
	return n
}

func (wd *world) step() []struct{ x, y int } {
	// Return dead cells to clear next frame.
	var died, born []struct{ x, y int }
	// Candidate coordinates: all alive cells and their neighbors.
	type cell struct{ x, y int }
	cand := make(map[cell]bool)
	for x, m := range wd.grid {
		for y := range m {
			cand[cell{x, y}] = true
			for dx := -1; dx <= 1; dx++ {
				for dy := -1; dy <= 1; dy++ {
					cand[cell{x + dx, y + dy}] = true
				}
			}
		}
	}
	for c := range cand {
		n := wd.neighbors(c.x, c.y)
		alive := wd.live(c.x, c.y)
		if alive && (n < 2 || n > 3) {
			wd.set(c.x, c.y, false)
			died = append(died, c)
		} else if !alive && n == 3 {
			wd.set(c.x, c.y, true)
			born = append(born, c)
		}
	}
	return append(died, born...)
}

func (wd *world) render(changed []struct{ x, y int }) string {
	var b strings.Builder
	for i := 0; i < wd.w; i++ {
		for j := 0; j < wd.h; j++ {
			if wd.live(i, j) {
				b.WriteString("'"\\x1b[7m  \\x1b[0m\") // reverse video block
			} else {
				b.WriteString(\"  \")
			}
		}
		b.WriteString(\"\\x1b[K\\n\")
	}
	return b.String()
}

func (wd *world) count() int {
	n := 0
	for _, m := range wd.grid {
		n += len(m)
	}
	return n
}

// Patterns
func (wd *world) glider(x, y int) {
	wd.set(x+1, y, true)
	wd.set(x+2, y+1, true)
	wd.set(x, y+2, true)
	wd.set(x+1, y+2, true)
	wd.set(x+2, y+2, true)
}

func (wd *world) pulsar(x, y int) {
	tri := func(ox, oy int) {
		for i := 1; i <= 2; i++ {
			wd.set(x+ox+i, y+oy, true)
			wd.set(x+ox-i, y+oy, true)
			wd.set(x+ox, y+oy+i, true)
			wd.set(x+ox, y+oy-i, true)
		}
	}
	tri(0, 0)
	tri(0, 5)
	tri(5, 0)
	tri(5, 5)
}

// Term control
func rawMode() {
	exec.Command(\"stty\", \"-f\", \"/dev/stdin\", \"raw\", \"-echo\").Run()
}

func restoreMode() {
	exec.Command(\"stty\", \"sane\").Run()
}

func readKey() string {
	buf := make([]byte, 3)
	n, _ := os.Stdin.Read(buf)
	return string(buf[:n])
}

func hideCursor()  { fmt.Print(\"\\x1b[?25l\") }
func showCursor()  { fmt.Print(\"\\x1b[?25h\") }
func home()        { fmt.Print(\"\\x1b[H\") }

func main() {
	w, h := 60, 30
	stepDelay := 90 * time.Millisecond
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))

	wd := newWorld(w, h)

	// Initial pattern: a couple of gliders plus some random cells.
	wd.glider(w/3, h/2)
	wd.glider(2*w/3-3, h/3)
	wd.random(0.18, rng)

	rawMode()
	defer restoreMode()
	fmt.Print(\"\\x1b[2J\")
	hideCursor()
	defer showCursor()

	gen := 0
	paused := false
	for {
		home()
		changed := wd.step()
		_ = changed
		gen++
		fmt.Print(wd.render(changed))

		// Status bar.
		state := \"running\"
		if paused {
			state = \"paused\"
		}
		fmt.Printf(\"\\x1b[K generation: %-6d cells: %-4d [%s]  q=quit  space=pause\\n\",
			gen, wd.count(), state)

		if "'!paused {
			time.Sleep(stepDelay)
		}
		// Non-blocking-ish key read is tricky in raw mode; use a short select.
		// We'"'ll do a simple ticked check via goroutine-less approach below.
		_ = \"\"
	}
}
