func (wd *world) step() {
	type cell struct{ x, y int }
	cand := make(map[cell]bool)
	for x, m := range wd.grid {
		for y := range m {
			cand[cell{x, y}] = true
			for dx := -1; dx <= 1; dx++ {
				for dy := -1; dy <= 1; dy++ {
					cand[cell{x + dx, y + dy}] = true
				}
			}
		}
	}
	var died, born []cell
	for c := range cand {
		n := wd.neighbors(c.x, c.y)
		alive := wd.live(c.x, c.y)
		if alive && (n < 2 || n > 3) {
			wd.set(c.x, c.y, false)
			died = append(died, c)
		} else if !alive && n == 3 {
			wd.set(c.x, c.y, true)
			born = append(born, c)
		}
	}
	_ , _ = died, born
}

